<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {CalendarDays,RefreshCw} from 'lucide-vue-next'
import type {Capsule} from '@/types'
import WaxSeal from './WaxSeal.vue'
import {capsuleReadPhase,canReadCapsule} from '@/composables/capsulePresentation'
import {readViewState,writeViewState} from '@/composables/viewState'
const props=defineProps<{capsule:Capsule;checking?:boolean}>()
const emit=defineEmits<{refresh:[]}>()
const reduced=()=>typeof window!=='undefined'&&window.matchMedia('(prefers-reduced-motion: reduce)').matches
const phase=ref<string>(capsuleReadPhase(props.capsule.opened,Boolean(readViewState(`capsule-read:${props.capsule.id}`)),reduced()))
let timer:ReturnType<typeof setTimeout>|undefined
watch(()=>[props.capsule.id,props.capsule.opened],()=>{if(timer)clearTimeout(timer);phase.value=capsuleReadPhase(props.capsule.opened,Boolean(readViewState(`capsule-read:${props.capsule.id}`)),reduced())})
function unseal(){if(!props.capsule.opened||phase.value==='opening')return;if(reduced()){phase.value='read';writeViewState(`capsule-read:${props.capsule.id}`,true);return}phase.value='opening';timer=setTimeout(()=>{if(props.capsule.opened){phase.value='read';writeViewState(`capsule-read:${props.capsule.id}`,true)}},700)}
const readable=computed(()=>canReadCapsule(props.capsule.opened,phase.value))
onBeforeUnmount(()=>{if(timer)clearTimeout(timer)})
</script>
<template><article class="capsule-letter sky-reading" :class="{'is-opening':phase==='opening'}"><header><p>{{capsule.opened?'约定的日子，已经到了':'把心意，交给时间保管'}}</p><h1>{{capsule.title}}</h1><span>写给 {{capsule.recipient||'未来的我们'}}</span><div class="letter-date"><CalendarDays :size="14"/>{{capsule.openDate}} 开启</div></header><Transition name="letter-copy" mode="out-in"><div v-if="readable" key="read" class="letter-copy sky-reading-copy">{{capsule.content}}</div><div v-else key="seal" class="letter-sealed"><button v-if="capsule.opened" class="letter-seal-button" :disabled="phase==='opening'" aria-label="开启这封信" @click="unseal"><WaxSeal/><span>{{phase==='opening'?'正在展开这封信…':'轻启封印，读一封来信'}}</span></button><template v-else><WaxSeal/><h2>这封信还在时间里旅行</h2><p>距离约定还有 {{Math.max(0,capsule.daysRemaining)}} 天</p><button class="sky-secondary" :disabled="checking" @click="emit('refresh')"><RefreshCw :size="14" :class="{'animate-spin':checking}"/>{{checking?'正在确认…':'查看开启状态'}}</button></template><i v-for="i in 8" :key="i" class="letter-spark" :style="{'--angle':`${i*45}deg`}"></i></div></Transition><footer>由 {{capsule.creatorName}} 于 {{capsule.createdAt}} 封存</footer></article></template>
<style scoped>
.capsule-letter{margin-top:24px;overflow:hidden;background:radial-gradient(ellipse at 85% 5%,#b1813e0a,transparent 55%),#1a1c20}.capsule-letter>header{text-align:center;padding:35px 30px 26px;border-bottom:1px solid #e2b8731c}.capsule-letter>header>p{color:#c5a46f;font-size:12px;letter-spacing:.12em}.capsule-letter h1{font-family:Georgia,"Songti SC",serif;font-size:29px;font-weight:500;line-height:1.5;margin:13px 0 9px;color:#eee2cf}.capsule-letter>header>span{font-size:13px;color:#b7aa96}.letter-date{display:flex;justify-content:center;gap:6px;align-items:center;margin-top:18px;color:#a39a8a;font-size:12px}.letter-sealed{position:relative;display:flex;flex-direction:column;align-items:center;padding:38px 22px;min-height:235px;background:linear-gradient(135deg,#e2b87303,transparent)}.letter-sealed h2{font-size:18px;font-weight:450;margin-top:17px;color:#d9c9b2}.letter-sealed p{font-size:13px;color:#a99e8b;margin-top:9px}.letter-sealed .sky-secondary{margin-top:20px}.letter-seal-button{display:flex;flex-direction:column;align-items:center;gap:20px;min-height:120px;color:#d5bb96;font-size:13px;border:0;background:none}.letter-seal-button:hover :deep(.wax-seal){box-shadow:inset 0 2px 4px #edc4a355,0 0 25px #ba7b5530}.letter-copy{padding:32px 38px;white-space:pre-wrap;overflow-wrap:anywhere}.capsule-letter>footer{padding:19px 30px;border-top:1px solid #e2b87316;font-size:11px;color:#9d9283}.letter-copy-enter-active{transition:opacity .65s,transform .65s}.letter-copy-leave-active{transition:opacity .15s}.letter-copy-enter-from{opacity:0;transform:translateY(9px)}.letter-copy-leave-to{opacity:0}.is-opening :deep(.wax-seal){animation:seal-melt .7s ease-in both}.letter-spark{position:absolute;left:50%;top:65px;width:3px;height:3px;border-radius:50%;background:#e2b873;opacity:0;pointer-events:none}.is-opening .letter-spark{animation:seal-spark .7s ease-out both}@keyframes seal-melt{to{transform:scale(1.18);filter:blur(9px);opacity:0}}@keyframes seal-spark{20%{opacity:.7}100%{transform:rotate(var(--angle)) translateX(80px);opacity:0}}
@media(max-width:639px){.capsule-letter h1{font-size:24px}.capsule-letter>header{padding:28px 22px 23px}.letter-copy{padding:25px 22px}}@media(prefers-reduced-motion:reduce){.is-opening :deep(.wax-seal),.is-opening .letter-spark{animation:none}.letter-copy-enter-active,.letter-copy-leave-active{transition:none}}
</style>
